// Un store mínimo: guarda el estado, lo cambia y avisa solo cuando el pedazo que te interesa cambió.
function crearStore(inicial) {
  let estado = inicial;
  const oyentes = new Set();
  return {
    obtener: () => estado,
    poner(cambio) {
      const nuevo = { ...estado, ...(typeof cambio === 'function' ? cambio(estado) : cambio) };
      const viejo = estado; estado = nuevo;
      oyentes.forEach((o) => o(estado, viejo));
    },
    suscribir(selector, alCambiar) {          // un «selector»: función que elige un pedazo del estado
      const o = (nuevo, viejo) => { if (!Object.is(selector(nuevo), selector(viejo))) alCambiar(selector(nuevo)); };
      oyentes.add(o);
      return () => oyentes.delete(o);          // devuelve cómo darse de baja
    },
  };
}

const store = crearStore({ talentos: 0, vidas: 5, tema: 'indigo' });
const avisos = { talentos: 0, vidas: 0, tema: 0 };
store.suscribir((s) => s.talentos, (v) => { avisos.talentos++; console.log('talentos ->', v); });
store.suscribir((s) => s.vidas, (v) => { avisos.vidas++; console.log('vidas ->', v); });
store.suscribir((s) => s.tema, (v) => { avisos.tema++; console.log('tema ->', v); });

store.poner((s) => ({ talentos: s.talentos + 10 }));
store.poner((s) => ({ talentos: s.talentos + 15 }));
store.poner({ vidas: 4 });
store.poner({ tema: 'indigo' });                // mismo valor: nadie se entera
console.log('avisos por pedazo:', JSON.stringify(avisos));
console.log('estado final:', JSON.stringify(store.obtener()));

import { create } from 'zustand';

const useJuego = create((set) => ({
  talentos: 0,
  vidas: 5,
  ganar: (n) => set((s) => ({ talentos: s.talentos + n })),    // set mezcla lo que le pasás con el estado
}));

function Saldo() {
  const t = useJuego((s) => s.talentos);       // se redibuja solo si cambia talentos
  return <b>{t}</b>;
}
function BotonGanar() {
  const ganar = useJuego((s) => s.ganar);      // la función no cambia nunca: este componente casi no se redibuja
  return <button onClick={() => ganar(10)}>+10</button>;
}

// Un reductor: una función pura (estado anterior, acción) -> estado nuevo.
function reductor(estado, accion) {
  switch (accion.tipo) {
    case 'ganar':   return { ...estado, talentos: estado.talentos + accion.cantidad };
    case 'perder_vida': return { ...estado, vidas: Math.max(0, estado.vidas - 1) };
    case 'reiniciar':   return { talentos: 0, vidas: 5 };
    default: throw new Error('Acción desconocida: ' + accion.tipo);
  }
}
const inicial = { talentos: 0, vidas: 5 };
const acciones = [
  { tipo: 'ganar', cantidad: 10 },
  { tipo: 'perder_vida' },
  { tipo: 'ganar', cantidad: 15 },
  { tipo: 'perder_vida' },
];
let estado = inicial;
for (const a of acciones) { estado = reductor(estado, a); console.log(JSON.stringify(a).padEnd(36), '->', JSON.stringify(estado)); }

// Como las acciones son datos y el reductor es puro, se puede reproducir todo desde cero:
const repetido = acciones.reduce(reductor, inicial);
console.log('reproducido desde cero:', JSON.stringify(repetido), '| igual:', JSON.stringify(repetido) === JSON.stringify(estado));
console.log('el estado inicial quedó intacto:', JSON.stringify(inicial));

const rebanada = createSlice({
  name: 'cont',
  initialState: { a: 0, b: 0, c: 0, d: 0 },
  reducers: {
    sumar: (s, { payload }) => { s[payload] += 1; },    // parece mutar; Immer devuelve un estado nuevo
  },
});
const tienda = configureStore({ reducer: { cont: rebanada.reducer } });

// en un componente:
const v = useSelector((s) => s.cont.a);                 // el selector, igual que en zustand
const dispatch = useDispatch();
dispatch(rebanada.actions.sumar('a'));                  // emite la acción { type: 'cont/sumar', payload: 'a' }

